296	+    );
297	+    assert!(r.get("errors").is_none(), "CREATE category failed: {r}");
298	+
299	+    let r = server.graphql_with_vars(
300	+        r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
301	+        serde_json::json!({ "sql": "CREATE TABLE bookmark (url TEXT, category TEXT REFERENCES category)" }),
302	+    );
303	+    assert!(r.get("errors").is_none(), "CREATE bookmark failed: {r}");
304	+
305	+    // Three categories, minted in ascending id order.
306	+    let mut category_ids = Vec::new();
307	+    for label in ["alpha", "beta", "gamma"] {
308	+        let r = server.graphql_with_vars(
309	+            r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
310	+            serde_json::json!({ "sql": format!("INSERT INTO category (label) VALUES ('{label}')") }),
311	+        );
312	+        assert!(
313	+            r.get("errors").is_none(),
314	+            "INSERT category {label} failed: {r}"
315	+        );
316	+        category_ids.push(
317	+            r["data"]["executeSql"]["message"]
318	+                .as_str()
319	+                .unwrap()
320	+                .to_string(),
321	+        );
322	+        std::thread::sleep(std::time::Duration::from_secs(1));
323	+    }
324	+
325	+    let r = server.graphql_with_vars(
326	+        r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
327	+        serde_json::json!({ "sql": "INSERT INTO bookmark (url) VALUES ('https://example.com')" }),
328	+    );
329	+    assert!(r.get("errors").is_none(), "INSERT bookmark failed: {r}");
330	+    let bm_id = r["data"]["executeSql"]["message"]
