337	+    // different answer than one that pins the first-*linked* junction row.
338	+    for cat_id in [&category_ids[2], &category_ids[0], &category_ids[1]] {
339	+        let r = server.graphql_with_vars(
340	+            r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
