12	fn race_graphql(server: &ServerGuard, mutations: &[String; 2]) -> [Value; 2] {
13	    let ready = Barrier::new(3);
14	    std::thread::scope(|scope| {
15	        let first = scope.spawn(|| {
16	            ready.wait();
17	            server.graphql(&mutations[0])
18	        });
19	        let second = scope.spawn(|| {
20	            ready.wait();
21	            server.graphql(&mutations[1])
22	        });
23	        ready.wait();
24	        [
25	            first.join().expect("first GraphQL writer panicked"),
26	            second.join().expect("second GraphQL writer panicked"),
27	        ]
28	    })
29	}
