31	fn graphql_winner(responses: &[Value; 2], table: &str) -> usize {
32	    for response in responses {
33	        assert!(
34	            !response
35	                .to_string()
36	                .to_ascii_lowercase()
37	                .contains("unique constraint failed"),
38	            "raw SQLite UNIQUE error leaked: {response}"
39	        );
40	    }
41	    assert_eq!(
42	        responses
43	            .iter()
44	            .filter(|r| r.get("errors").is_none())
45	            .count(),
46	        1,
47	        "expected exactly one GraphQL success: {responses:?}"
48	    );
49	    assert_eq!(
50	        responses
51	            .iter()
52	            .filter(|r| r.get("errors").is_some())
53	            .count(),
54	        1,
55	        "expected exactly one GraphQL error response: {responses:?}"
56	    );
57	    let winner = usize::from(responses[0].get("errors").is_some());
58	    let loser = &responses[1 - winner];
59	    let errors = loser["errors"].as_array().expect("errors must be an array");
60	    assert!(!errors.is_empty(), "loser has no error: {loser}");
61	    assert_eq!(errors[0]["extensions"]["code"], "SINGLETON_VIOLATION");
62	    assert_eq!(errors[0]["extensions"]["table"], table);
63	    winner
64	}
