147	    let repo = DdbTestRepo::init();
148	    let server = ServerGuard::start(&repo);
149	
150	    let r = server.graphql_with_vars(
151	        r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
152	        serde_json::json!({ "sql": "CREATE TABLE category (label TEXT)" }),
153	    );
154	    assert!(r.get("errors").is_none(), "CREATE category failed: {r}");
155	
156	    let r = server.graphql_with_vars(
157	        r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
158	        serde_json::json!({ "sql": "CREATE TABLE bookmark (url TEXT, category TEXT REFERENCES category)" }),
159	    );
160	    assert!(r.get("errors").is_none(), "CREATE bookmark failed: {r}");
161	
162	    // Three categories, minted in ascending id order.
163	    let mut category_ids = Vec::new();
164	    for label in ["alpha", "beta", "gamma"] {
165	        let r = server.graphql_with_vars(
166	            r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
167	            serde_json::json!({ "sql": format!("INSERT INTO category (label) VALUES ('{label}')") }),
168	        );
169	        assert!(
170	            r.get("errors").is_none(),
171	            "INSERT category {label} failed: {r}"
172	        );
173	        category_ids.push(
174	            r["data"]["executeSql"]["message"]
175	                .as_str()
176	                .unwrap()
177	                .to_string(),
178	        );
179	        std::thread::sleep(std::time::Duration::from_secs(1));
180	    }
181	
182	    let r = server.graphql_with_vars(
183	        r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
184	        serde_json::json!({ "sql": "INSERT INTO bookmark (url) VALUES ('https://example.com')" }),
185	    );
186	    assert!(r.get("errors").is_none(), "INSERT bookmark failed: {r}");
187	    let bm_id = r["data"]["executeSql"]["message"]
188	        .as_str()
189	        .unwrap()
190	        .to_string();
191	
192	    // Link the categories out of id order (gamma, alpha, beta) so a resolver
193	    // that picked the numerically smallest category id would give a
194	    // different answer than one that pins the first-*linked* junction row.
195	    for cat_id in [&category_ids[2], &category_ids[0], &category_ids[1]] {
196	        let r = server.graphql_with_vars(
197	            r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
198	            serde_json::json!({
199	                "sql": format!(
200	                    "INSERT INTO bookmark_category (bookmark_id, category_id) VALUES ('{bm_id}', '{cat_id}')"
201	                )
202	            }),
203	        );
204	        assert!(r.get("errors").is_none(), "INSERT junction failed: {r}");
205	    }
206	
207	    let r = server.graphql(r#"{ bookmarks { items { category_id } } }"#);
208	    assert!(r.get("errors").is_none(), "category_id query failed: {r}");
209	    let items = r["data"]["bookmarks"]["items"].as_array().unwrap();
210	    assert_eq!(items.len(), 1, "expected 1 bookmark: {r}");
211	    let raw_id = items[0]["category_id"]
212	        .as_str()
213	        .expect("category_id should be a non-null String");
214	    assert_eq!(
215	        raw_id, category_ids[2],
216	        "category_id must pin the first-linked category (gamma), not the numerically smallest one"
217	    );
218	}
