11	/// Locate the `ddb` binary in the workspace target directory.
12	/// `CARGO_BIN_EXE_ddb` is only set for same-package binaries, and the
13	/// `assert_cmd::cargo::cargo_bin` function is deprecated, so we resolve
14	/// the path ourselves.
15	pub(crate) fn ddb_bin() -> PathBuf {
16	    if let Ok(p) = std::env::var("CARGO_BIN_EXE_ddb") {
17	        return PathBuf::from(p);
18	    }
19	    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
20	    dir.pop(); // tests/ -> workspace root
21	    let target = std::env::var("CARGO_TARGET_DIR")
22	        .map(PathBuf::from)
23	        .unwrap_or_else(|_| dir.join("target"));
24	    let profile = if cfg!(debug_assertions) {
25	        "debug"
26	    } else {
27	        "release"
28	    };
29	    target
30	        .join(profile)
31	        .join(format!("ddb{}", std::env::consts::EXE_SUFFIX))
32	}
