47	/// RAII guard that starts a `ddb serve` process and kills it on drop.
48	pub struct ServerGuard {
49	    child: Child,
50	    pub port: u16,
51	    pub pg_port: u16,
52	    pub token: String,
53	}
54	
55	impl ServerGuard {
56	    pub fn start(repo: &DdbTestRepo) -> Self {
57	        let port = next_available_port();
58	        let pg_port = next_available_port();
59	        let log_dir = repo.path().join("dev/local/test-logs");
60	
61	        let mut child = std::process::Command::new(ddb_bin())
62	            .arg("--repo")
63	            .arg(repo.path())
64	            .arg("--log-dir")
65	            .arg(&log_dir)
66	            .arg("serve")
67	            .arg("--port")
68	            .arg(port.to_string())
69	            .arg("--pg-port")
70	            .arg(pg_port.to_string())
71	            .stderr(Stdio::piped())
72	            .spawn()
73	            .expect("failed to start server");
74	
75	        let stderr = child.stderr.take().unwrap();
76	        let reader = BufReader::new(stderr);
77	        let mut token = String::new();
78	        let mut http_ready = false;
79	        let mut pg_ready = false;
80	
81	        for line in reader.lines() {
82	            let line = line.unwrap();
83	            if line.contains("auth token:") {
84	                if let Some(path) = line.split("auth token: ").nth(1) {
85	                    token = std::fs::read_to_string(path.trim())
86	                        .unwrap_or_default()
87	                        .trim()
88	                        .to_string();
89	                }
90	            }
91	            if line.contains("pgwire listening on") {
92	                pg_ready = true;
93	            } else if line.contains("listening on") {
94	                http_ready = true;
95	            }
96	            if http_ready && pg_ready {
97	                break;
98	            }
99	        }
100	
101	        // Small delay for the TCP listener to be fully ready
102	        std::thread::sleep(Duration::from_millis(50));
103	        Self {
104	            child,
105	            port,
106	            pg_port,
107	            token,
108	        }
109	    }
