306	+    let mut category_ids = Vec::new();
307	+    for label in ["alpha", "beta", "gamma"] {
308	+        let r = server.graphql_with_vars(
309	+            r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
310	+            serde_json::json!({ "sql": format!("INSERT INTO category (label) VALUES ('{label}')") }),
311	+        );
