336	/// Read the next "next" message from WS, skipping pings.
337	pub fn read_next(
338	    ws: &mut tungstenite::WebSocket<tungstenite::stream::MaybeTlsStream<std::net::TcpStream>>,
339	) -> serde_json::Value {
340	    loop {
341	        let msg = ws.read().expect("ws read failed");
342	        if let Message::Text(text) = msg {
343	            let val: serde_json::Value = serde_json::from_str(&text).unwrap();
344	            if val["type"] == "next" {
345	                return val;
346	            }
347	            if val["type"] == "ping" {
348	                ws.send(Message::Text(
349	                    serde_json::json!({"type": "pong"}).to_string().into(),
350	                ))
351	                .ok();
352	                continue;
353	            }
354	            if val["type"] == "error" {
355	                panic!("subscription error: {val}");
356	            }
357	        }
358	    }
359	}
