66	/// Bind §55.E's materialized count to the sole committed row and its payload.
67	fn assert_survivor(repo: &DdbTestRepo, table: &str, theme: &str) -> String {
68	    let count = repo
69	        .ddb()
70	        .args(["query", &format!("SELECT COUNT(*) FROM {table}")])
71	        .assert()
72	        .success();
73	    assert_eq!(
74	        String::from_utf8_lossy(&count.get_output().stdout).trim(),
75	        "1",
76	        "§55.E: {table} must converge on exactly one row"
77	    );
78	    let row_id = repo
79	        .ddb()
80	        .args(["query", &format!("SELECT id FROM {table}")])
81	        .assert()
82	        .success();
83	    let id = String::from_utf8_lossy(&row_id.get_output().stdout)
84	        .trim()
85	        .to_owned();
86	    assert_doogat_id(&id);
87	    let row_theme = repo
88	        .ddb()
89	        .args(["query", &format!("SELECT theme FROM {table}")])
90	        .assert()
91	        .success();
92	    assert_eq!(
93	        String::from_utf8_lossy(&row_theme.get_output().stdout).trim(),
94	        theme,
95	        "surviving row must match the successful writer"
96	    );
97	
98	    let tree = Command::new("git")
99	        .current_dir(repo.path())
100	        .args(["ls-tree", "--name-only", "HEAD:ddb"])
101	        .output()
102	        .expect("git ls-tree failed to run");
103	    assert!(tree.status.success(), "git ls-tree failed: {tree:?}");
104	    let tree_stdout = String::from_utf8_lossy(&tree.stdout);
105	    let committed_ids: Vec<&str> = tree_stdout
106	        .lines()
107	        .filter_map(|path| path.strip_suffix(".md"))
108	        .collect();
109	    assert_eq!(
110	        committed_ids,
111	        [id.as_str()],
112	        "HEAD must contain exactly the surviving row"
113	    );
114	    let committed = Command::new("git")
115	        .current_dir(repo.path())
116	        .args(["show", &format!("HEAD:ddb/{id}.md")])
117	        .output()
118	        .expect("git show failed to run");
119	    assert!(committed.status.success(), "git show failed: {committed:?}");
120	    assert!(
121	        String::from_utf8_lossy(&committed.stdout).contains(theme),
122	        "winner's theme {theme:?} must be durable in HEAD: {committed:?}"
123	    );
124	    id
125	}
