127	#[test]
128	fn integration_55_b_graphql_execute_sql_singleton_insert_race() {
129	    let repo = DdbTestRepo::init();
130	    repo.ddb()
131	        .args(["query", "CREATE TABLE ig_race_sql (theme TEXT) SINGLETON"])
132	        .assert()
133	        .success();
134	    let server = ServerGuard::start(&repo);
135	    let themes = ["sql-dark", "sql-light"];
136	    let mutations = themes.map(|theme| {
137	        format!(
138	            r#"mutation {{ executeSql(sql: "INSERT INTO ig_race_sql (title, theme) VALUES ('x', '{theme}')") {{ message }} }}"#
139	        )
140	    });
141	    let responses = race_graphql(&server, &mutations);
142	    let winner = graphql_winner(&responses, "ig_race_sql");
143	    let result = &responses[winner]["data"]["executeSql"];
144	    let winner_id = result["message"]
145	        .as_str()
146	        .expect("INSERT must return an id");
147	    let survivor = assert_survivor(&repo, "ig_race_sql", themes[winner]);
148	    assert_eq!(survivor, winner_id.trim());
149	
150	    // §55.B also requires the generated singleton GraphQL field to stay readable.
151	    let query = server.graphql("{ ig_race_sql { id theme } }");
152	    assert!(
153	        query.get("errors").is_none(),
154	        "singleton query failed: {query}"
155	    );
156	    assert_eq!(query["data"]["ig_race_sql"]["id"], survivor);
157	    assert_eq!(query["data"]["ig_race_sql"]["theme"], themes[winner]);
158	}
