185	#[test]
186	fn integration_55_d_cli_vs_pgwire_singleton_insert_race() {
187	    let repo = DdbTestRepo::init();
188	    repo.ddb()
189	        .args(["query", "CREATE TABLE ig_race_pg (theme TEXT) SINGLETON"])
190	        .assert()
191	        .success();
192	    let server = ServerGuard::start(&repo);
193	    let runtime = tokio::runtime::Runtime::new().expect("Tokio runtime failed");
194	    let (client, connection) = runtime.block_on(async {
195	        tokio::time::timeout(
196	            Duration::from_secs(30),
197	            tokio_postgres::Config::new()
198	                .host("127.0.0.1")
199	                .port(server.pg_port)
200	                .user("ddb")
201	                .password(&server.token)
202	                .dbname("ddb")
203	                .connect(tokio_postgres::NoTls),
204	        )
205	        .await
206	        .expect("PgWire connect timed out")
207	        .expect("PgWire connect failed")
208	    });
209	    let connection_task = runtime.spawn(connection);
210	
211	    let ready = Barrier::new(2);
212	    let (cli, pg) = std::thread::scope(|scope| {
213	        let cli_writer = scope.spawn(|| {
214	            ready.wait();
215	            repo.ddb()
216	                .args([
217	                    "create",
218	                    "--type",
219	                    "ig_race_pg",
220	                    "--title",
221	                    "x",
222	                    "--set",
223	                    "theme=cli-dark",
224	                ])
225	                .timeout(Duration::from_secs(30))
226	                .output()
227	                .expect("CLI writer failed to run")
228	        });
229	        ready.wait();
230	        let pg = runtime.block_on(async {
231	            tokio::time::timeout(
232	                Duration::from_secs(30),
233	                client
234	                    .simple_query("INSERT INTO ig_race_pg (title, theme) VALUES ('x', 'pg-light')"),
235	            )
236	            .await
237	            .expect("PgWire INSERT timed out")
238	        });
239	        (cli_writer.join().expect("CLI writer panicked"), pg)
240	    });
241	
242	    let successes = [cli.status.success(), pg.is_ok()];
243	    assert_eq!(
244	        successes.iter().filter(|&&ok| ok).count(),
245	        1,
246	        "expected one winner: CLI={cli:?}, PgWire={pg:?}"
247	    );
248	    assert_eq!(
249	        successes.iter().filter(|&&ok| !ok).count(),
250	        1,
251	        "expected one loser: CLI={cli:?}, PgWire={pg:?}"
252	    );
253	    let loser_message = match &pg {
254	        Ok(messages) => {
255	            assert!(
256	                messages
257	                    .iter()
258	                    .any(|message| matches!(message, SimpleQueryMessage::CommandComplete(1))),
259	                "PgWire winner must report one inserted row: {messages:?}"
260	            );
261	            format!(
262	                "{}\n{}",
263	                String::from_utf8_lossy(&cli.stdout),
264	                String::from_utf8_lossy(&cli.stderr)
265	            )
266	        }
267	        Err(error) => error
268	            .as_db_error()
269	            .expect("PgWire loser must return a database error, not lose the connection")
270	            .message()
271	            .to_owned(),
272	    };
273	    let normalized = loser_message.to_ascii_lowercase();
274	    assert!(
275	        !normalized.contains("unique constraint failed"),
276	        "raw SQLite UNIQUE error leaked: {loser_message}"
277	    );
278	    // §55.D deliberately allows recognized transient contention. Do not turn
279	    // this into the stronger, actor-serialized §55.B/C error contract.
280	    assert!(
281	        [
282	            "singleton constraint",
283	            "locked",
284	            "busy",
285	            "index.lock",
286	            "cannot lock",
287	            "unable to create",
288	            "file exists",
289	            "another git process",
290	        ]
291	        .iter()
292	        .any(|fragment| normalized.contains(fragment)),
293	        "unrecognized CLI/PgWire loser error: {loser_message}"
294	    );
295	
296	    // Use the same PgWire connection after either outcome, including a rejected
297	    // INSERT. Both protocol convergence and connection usability must hold.
298	    let count = runtime.block_on(async {
299	        tokio::time::timeout(
300	            Duration::from_secs(30),
301	            client.simple_query("SELECT COUNT(*) FROM ig_race_pg"),
302	        )
303	        .await
304	        .expect("PgWire count timed out")
305	        .expect("PgWire connection must remain usable after the race")
306	    });
307	    let rows: Vec<_> = count
308	        .iter()
309	        .filter_map(|message| match message {
310	            SimpleQueryMessage::Row(row) => Some(row),
311	            _ => None,
312	        })
313	        .collect();
314	    assert_eq!(rows.len(), 1, "COUNT must return exactly one result row");
315	    assert_eq!(
316	        rows[0].get(0),
317	        Some("1"),
318	        "§55.E: PgWire must see one survivor"
319	    );
320	
321	    let theme = if cli.status.success() {
322	        "cli-dark"
323	    } else {
324	        "pg-light"
325	    };
326	    let survivor = assert_survivor(&repo, "ig_race_pg", theme);
327	    if cli.status.success() {
328	        assert_eq!(String::from_utf8_lossy(&cli.stdout).trim(), survivor);
329	    }
330	    drop(client);
331	    runtime.block_on(async {
332	        tokio::time::timeout(Duration::from_secs(30), connection_task)
333	            .await
334	            .expect("PgWire connection shutdown timed out")
335	            .expect("PgWire driver panicked")
336	            .expect("PgWire driver failed");
337	    });
338	}
