34	static SERVER_PORT_COUNTER: AtomicU16 = AtomicU16::new(19100);
35	
36	/// Claim the next port from the atomic counter, skipping any that are
37	/// already bound by another process.
38	fn next_available_port() -> u16 {
39	    loop {
40	        let candidate = SERVER_PORT_COUNTER.fetch_add(1, Ordering::SeqCst);
41	        if std::net::TcpListener::bind(("127.0.0.1", candidate)).is_ok() {
42	            return candidate;
43	        }
44	    }
45	}
