191	    /// Open a graphql-ws WebSocket connection with auth.
192	    pub fn ws_connect(
193	        &self,
194	    ) -> tungstenite::WebSocket<tungstenite::stream::MaybeTlsStream<std::net::TcpStream>> {
195	        let request = Request::builder()
196	            .uri(format!("ws://127.0.0.1:{}/ws", self.port))
197	            .header("Authorization", format!("Bearer {}", self.token))
198	            .header("Sec-WebSocket-Protocol", "graphql-transport-ws")
199	            .header("Host", format!("127.0.0.1:{}", self.port))
200	            .header("Connection", "Upgrade")
201	            .header("Upgrade", "websocket")
202	            .header("Sec-WebSocket-Version", "13")
203	            .header(
204	                "Sec-WebSocket-Key",
205	                tungstenite::handshake::client::generate_key(),
206	            )
207	            .body(())
208	            .unwrap();
209	
210	        let (ws, _resp) = connect(request).expect("WebSocket connect failed");
211	        ws
212	    }
213	
214	    /// Init graphql-ws protocol and subscribe, returns the connected socket.
215	    pub fn ws_subscribe(
216	        &self,
217	        subscription_query: &str,
218	    ) -> tungstenite::WebSocket<tungstenite::stream::MaybeTlsStream<std::net::TcpStream>> {
219	        let mut ws = self.ws_connect();
220	
221	        // connection_init
222	        ws.send(Message::Text(
223	            serde_json::json!({"type": "connection_init", "payload": {}})
224	                .to_string()
225	                .into(),
226	        ))
227	        .unwrap();
228	
229	        // Wait for connection_ack
230	        let ack = ws.read().expect("no ack");
231	        let ack: serde_json::Value = serde_json::from_str(ack.to_text().unwrap()).unwrap();
232	        assert_eq!(ack["type"], "connection_ack");
233	
234	        // Subscribe
235	        ws.send(Message::Text(
236	            serde_json::json!({
237	                "type": "subscribe",
238	                "id": "1",
239	                "payload": { "query": subscription_query }
240	            })
241	            .to_string()
242	            .into(),
243	        ))
244	        .unwrap();
245	
246	        // Set read timeout to avoid blocking forever
247	        if let tungstenite::stream::MaybeTlsStream::Plain(ref s) = ws.get_ref() {
248	            s.set_read_timeout(Some(Duration::from_secs(30))).unwrap();
249	        }
250	
251	        ws
252	    }
