254	    /// Open a graphql-ws WebSocket connection WITHOUT an Authorization header.
255	    /// Browser clients can't set headers on WebSocket, so this simulates that.
256	    pub fn ws_connect_no_header(
257	        &self,
258	    ) -> tungstenite::WebSocket<tungstenite::stream::MaybeTlsStream<std::net::TcpStream>> {
259	        let request = Request::builder()
260	            .uri(format!("ws://127.0.0.1:{}/ws", self.port))
261	            .header("Sec-WebSocket-Protocol", "graphql-transport-ws")
262	            .header("Host", format!("127.0.0.1:{}", self.port))
263	            .header("Connection", "Upgrade")
264	            .header("Upgrade", "websocket")
265	            .header("Sec-WebSocket-Version", "13")
266	            .header(
267	                "Sec-WebSocket-Key",
268	                tungstenite::handshake::client::generate_key(),
269	            )
270	            .body(())
271	            .unwrap();
