277	    /// Connect without header, authenticate via connection_init payload, subscribe.
278	    pub fn ws_subscribe_with_payload_auth(
279	        &self,
280	        subscription_query: &str,
281	    ) -> tungstenite::WebSocket<tungstenite::stream::MaybeTlsStream<std::net::TcpStream>> {
282	        let mut ws = self.ws_connect_no_header();
283	
284	        // connection_init with bearer token in payload
285	        ws.send(Message::Text(
286	            serde_json::json!({
287	                "type": "connection_init",
288	                "payload": { "Authorization": format!("Bearer {}", self.token) }
289	            })
290	            .to_string()
291	            .into(),
292	        ))
293	        .unwrap();
294	
295	        // Wait for connection_ack
296	        let ack = ws.read().expect("no ack");
297	        let ack: serde_json::Value = serde_json::from_str(ack.to_text().unwrap()).unwrap();
298	        assert_eq!(ack["type"], "connection_ack");
299	
300	        // Subscribe
301	        ws.send(Message::Text(
302	            serde_json::json!({
303	                "type": "subscribe",
304	                "id": "1",
305	                "payload": { "query": subscription_query }
306	            })
307	            .to_string()
308	            .into(),
309	        ))
310	        .unwrap();
311	
312	        // Set read timeout to avoid blocking forever
313	        if let tungstenite::stream::MaybeTlsStream::Plain(ref s) = ws.get_ref() {
314	            s.set_read_timeout(Some(Duration::from_secs(30))).unwrap();
315	        }
316	
317	        ws
318	    }
