361	/// Run a `SELECT ...` via `executeSql` and return the first row's first
362	/// column as a string. `executeSql`'s `rows` field for a SELECT is a list
363	/// of JSON-stringified row arrays (e.g. `rows: ["[\"0\"]"]`), so this
364	/// parses the first element as JSON and indexes into it.
365	pub fn select_scalar(server: &ServerGuard, sql: &str) -> String {
366	    let escaped = sql.replace('"', "\\\"");
367	    let query = format!(r#"mutation {{ executeSql(sql: "{escaped}") {{ rows }} }}"#);
368	    let result = server.graphql(&query);
369	    assert!(result.get("errors").is_none(), "SELECT failed: {result}");
370	    let rows = result["data"]["executeSql"]["rows"].as_array().unwrap();
371	    let row_json = rows[0].as_str().unwrap();
372	    let row: Vec<String> = serde_json::from_str(row_json).unwrap();
373	    row[0].clone()
374	}
