501	impl MultiNodeSetup {
502	    /// Create a bare remote and N nodes.
503	    /// Node 0 initializes the repo and pushes; nodes 1..N clone.
504	    pub fn new(n: usize) -> Self {
505	        assert!(n >= 2, "need at least 2 nodes");
506	
507	        let remote_dir = TempDir::new().unwrap();
508	        std::process::Command::new("git")
509	            .args(["init", "--bare"])
510	            .arg(remote_dir.path())
511	            .output()
512	            .unwrap();
513	
514	        let mut nodes = Vec::with_capacity(n);
515	        let mut temps = Vec::with_capacity(n);
516	
517	        // Node 0: init + push
518	        let dir0 = TempDir::new().unwrap();
519	        let path0 = dir0.path().to_path_buf();
520	        DdbTestRepo::ddb_at(&path0)
521	            .arg("init")
522	            .arg(&path0)
523	            .assert()
524	            .success();
525	        DdbTestRepo::disable_git_signing(&path0);
526	        std::process::Command::new("git")
527	            .current_dir(&path0)
528	            .args(["remote", "add", "origin"])
529	            .arg(remote_dir.path())
530	            .output()
531	            .unwrap();
532	        DdbTestRepo::ddb_at(&path0)
533	            .args(["register-node", "Node-0"])
534	            .assert()
535	            .success();
536	        Self::git_push(&path0);
537	        nodes.push(path0);
538	        temps.push(dir0);
539	
540	        // Nodes 1..N: clone + register
541	        for i in 1..n {
542	            let dir = TempDir::new().unwrap();
543	            let path = dir.path().join("repo");
544	            std::process::Command::new("git")
545	                .args(["clone"])
546	                .arg(remote_dir.path())
547	                .arg(&path)
548	                .output()
549	                .unwrap();
550	            DdbTestRepo::disable_git_signing(&path);
551	            DdbTestRepo::ddb_at(&path)
552	                .args(["register-node", &format!("Node-{i}")])
553	                .assert()
554	                .success();
555	            nodes.push(path);
556	            temps.push(dir);
557	        }
558	
559	        Self {
560	            remote_dir,
561	            nodes,
562	            _temps: temps,
563	        }
564	    }
