120	        r#"mutation($sql: String!) { executeSql(sql: $sql) { message } }"#,
121	        serde_json::json!({ "sql": "CREATE TABLE item (category TEXT, priority INTEGER)" }),
122	    );
123	    assert!(
124	        result.get("errors").is_none(),
125	        "CREATE TABLE item failed: {result}"
126	    );
127	
128	    // Create a typed doogat via REST with fields
129	    let resp = server.rest_post(
130	        "/doogats",
131	        json!({
132	            "title": "REST Typed Item",
133	            "type": "item",
134	            "fields": "{\"category\":\"books\",\"priority\":\"1\"}"
135	        }),
136	    );
137	    assert_eq!(
138	        resp.status(),
139	        201,
140	        "typed create should return 201 Created"
141	    );
142	    let body: Value = resp.json().expect("invalid json");
143	    let id = body["data"]["id"]
144	        .as_str()
145	        .expect("created object missing id")
146	        .to_string();
147	    assert!(!id.is_empty(), "created id must not be empty");
148	    assert_eq!(body["data"]["title"], "REST Typed Item");
149	    assert_eq!(
150	        body["data"]["type"], "item",
151	        "created doogat must carry the registered type"
152	    );
153	
154	    // Verify typed columns are populated by reading the materialized row back.
155	    assert_item_typed_columns_roundtrip(&server, &id);
156	
157	    // Cross-process read-back: confirm the typed column is durable and
158	    // readable through a separate `ddb query` CLI process, not just the
159	    // same server's executeSql.
160	    repo.ddb()
161	        .args([
162	            "query",
163	            &format!("SELECT category FROM item WHERE id = '{id}'"),
164	        ])
165	        .assert()
166	        .success()
167	        .stdout(predicate::str::contains("books"));
