170	/// Read the materialized `item` row back via `executeSql` (format:"objects") and
171	/// assert the typed columns set by the REST typed-create round-trip exactly.
172	fn assert_item_typed_columns_roundtrip(server: &ServerGuard, id: &str) {
173	    // A SELECT via executeSql with format:"objects" returns parsed rows, not a
174	    // `message` (which carries DDL/DML status).
175	    let select = server.graphql_with_vars(
176	        r#"mutation($sql: String!, $fmt: String) { executeSql(sql: $sql, format: $fmt) { rows } }"#,
177	        serde_json::json!({
178	            "sql": format!("SELECT category, priority FROM item WHERE id = '{id}'"),
179	            "fmt": "objects"
180	        }),
181	    );
182	    assert!(
183	        select.get("errors").is_none(),
184	        "SELECT from item failed: {select}"
185	    );
186	    let rows = select["data"]["executeSql"]["rows"]
187	        .as_array()
188	        .expect("executeSql missing rows");
189	    assert_eq!(rows.len(), 1, "expected exactly one materialized row, got: {select}");
190	    let row: Value = serde_json::from_str(rows[0].as_str().expect("row not a string"))
191	        .expect("row not valid json");
192	    assert_eq!(
193	        row["category"].as_str(),
194	        Some("books"),
195	        "category typed column must round-trip exactly, got row: {row}"
196	    );
197	    let priority = &row["priority"];
198	    assert!(
199	        priority.as_i64() == Some(1) || priority.as_str() == Some("1"),
200	        "priority typed column must round-trip as 1, got row: {row}"
201	    );
202	}
