11	    /// Collect referenced types that use folder storage (for path-qualified wikilinks).
12	    pub(super) fn ref_folder_types(
13	        &self,
14	        schema: &TableSchema,
15	    ) -> std::collections::HashSet<String> {
16	        schema
17	            .columns
18	            .iter()
19	            .filter_map(|c| c.references.as_ref())
20	            .filter(|ref_table| self.index.type_uses_folder(ref_table, self.repo))
21	            .cloned()
22	            .collect()
