25	    pub(super) fn resolve_junction_table(
26	        &mut self,
27	        table_name: &str,
28	    ) -> Result<Option<(String, String)>> {
29	        // Try each possible split point of `type_col`
30	        for (i, _) in table_name.match_indices('_') {
31	            let candidate_type = &table_name[..i];
32	            let candidate_col = &table_name[i + 1..];
33	            if candidate_type.is_empty() || candidate_col.is_empty() {
34	                continue;
35	            }
36	            // Check if candidate_type is a known typedef
37	            if self.load_typedef_location(candidate_type).is_ok() {
38	                let schema = self.load_schema(candidate_type)?;
39	                // Check if candidate_col is a REFERENCES column
40	                if schema
41	                    .columns
42	                    .iter()
43	                    .any(|c| c.name == candidate_col && c.references.is_some())
44	                {
45	                    return Ok(Some((
46	                        candidate_type.to_string(),
47	                        candidate_col.to_string(),
48	                    )));
49	                }
50	            }
51	        }
52	        Ok(None)
53	    }
