55	    /// Handle INSERT into a junction table by appending reference lines to the
56	    /// parent doogat and re-indexing.
57	    pub(super) fn handle_junction_insert(
58	        &mut self,
59	        ins: &sqlparser::ast::Insert,
60	        type_name: &str,
61	        col_name: &str,
62	    ) -> Result<SqlResult> {
63	        let col_names: Vec<String> = ins.columns.iter().map(|c| c.value.to_lowercase()).collect();
64	        let type_id_col = format!("{type_name}_id");
65	        let ref_id_col = format!("{col_name}_id");
66	
67	        let rows = match ins.source.as_ref() {
68	            Some(query) => match query.body.as_ref() {
69	                SetExpr::Values(v) => {
70	                    let mut rows = Vec::with_capacity(v.rows.len());
71	                    for row in &v.rows {
72	                        rows.push(eval_values(self.index.sql_conn(), row)?);
73	                    }
74	                    rows
75	                }
76	                _ => {
77	                    return Err(DoogatError::SqlEngine(
78	                        "only VALUES clause supported for junction INSERT".into(),
79	                    ))
80	                }
81	            },
82	            None => return Err(DoogatError::SqlEngine("missing VALUES clause".into())),
83	        };
84	
85	        let schema = self.load_schema(type_name)?;
86	        let ref_col = schema
87	            .columns
88	            .iter()
89	            .find(|c| c.name == col_name && c.references.is_some())
90	            .ok_or_else(|| {
91	                DoogatError::SqlEngine(format!(
92	                    "column {col_name} not found or not a REFERENCES column"
93	                ))
94	            })?;
95	        let ref_folder_types = self.ref_folder_types(&schema);
96	
97	        let mut affected = 0;
98	        for row_values in &rows {
99	            let parent_id_idx = col_names
100	                .iter()
101	                .position(|c| *c == type_id_col)
102	                .ok_or_else(|| {
103	                    DoogatError::SqlEngine(format!("missing {type_id_col} column in INSERT"))
104	                })?;
105	            let target_id_idx =
106	                col_names
107	                    .iter()
108	                    .position(|c| *c == ref_id_col)
109	                    .ok_or_else(|| {
110	                        DoogatError::SqlEngine(format!("missing {ref_id_col} column in INSERT"))
111	                    })?;
112	
113	            let parent_id = &row_values[parent_id_idx];
114	            let target_id = &row_values[target_id_idx];
115	
116	            // Read parent doogat (txn-aware: picks up buffered writes)
117	            let path = self.index.resolve_path(parent_id)?;
118	            let content = self.read_content(&path)?;
119	            let mut parsed = parser::parse(&content, &path)?;
120	
121	            // Build the reference line with folder-qualified link if needed
122	            let link_target = if let Some(ref ref_table) = ref_col.references {
123	                if ref_folder_types.contains(ref_table) {
124	                    format!("ddb/{ref_table}/{target_id}.md")
125	                } else {
126	                    target_id.clone()
127	                }
128	            } else {
129	                target_id.clone()
130	            };
131	            let ref_line = format!("- {}:: [[{}]]", col_name, link_target);
132	
133	            // Skip if reference line already exists (idempotent, 0 affected)
134	            if parsed
135	                .reference_section
136	                .lines()
137	                .any(|line| line.trim() == ref_line.trim())
138	            {
139	                continue;
140	            }
141	
142	            // Append to reference section
143	            let trimmed = parsed.reference_section.trim_end();
144	            parsed.reference_section = if trimmed.is_empty() {
145	                format!("{ref_line}\n")
146	            } else {
147	                format!("{trimmed}\n{ref_line}\n")
148	            };
149	
150	            // Serialize
151	            let new_content = parser::serialize(&parsed);
152	
153	            // Re-index this doogat
154	            let re_parsed = parser::parse(&new_content, &path)?;
155	            self.index.index_doogat(&re_parsed)?;
156	            self.index
157	                .materialize_single(&schema, parent_id, &re_parsed)?;
158	
159	            if let Some(ref mut buf) = self.txn {
160	                buf.writes.push(PendingWrite {
161	                    path,
162	                    content: new_content,
163	                });
164	            } else {
165	                self.repo.commit_file(
166	                    &path,
167	                    &new_content,
168	                    &format!("add {col_name} ref {target_id} to {type_name} {parent_id}"),
169	                )?;
170	            }
171	
172	            affected += 1;
173	        }
174	
175	        Ok(SqlResult::Affected(affected))
176	    }
