178	    /// Handle DELETE from a junction table by removing matching reference lines
179	    /// from the parent doogat and re-indexing.
180	    pub(super) fn handle_junction_delete(
181	        &mut self,
182	        type_name: &str,
183	        col_name: &str,
184	        parent_id: &str,
185	        target_id: &str,
186	    ) -> Result<SqlResult> {
187	        let schema = self.load_schema(type_name)?;
188	        let ref_col = schema
189	            .columns
190	            .iter()
191	            .find(|c| c.name == col_name && c.references.is_some())
192	            .ok_or_else(|| {
193	                DoogatError::SqlEngine(format!(
194	                    "column {col_name} not found or not a REFERENCES column"
195	                ))
196	            })?;
197	        let ref_folder_types = self.ref_folder_types(&schema);
198	
199	        // Read parent doogat (txn-aware: picks up buffered writes)
200	        let path = self.index.resolve_path(parent_id)?;
201	        let content = self.read_content(&path)?;
202	        let mut parsed = parser::parse(&content, &path)?;
203	
204	        // Build the reference line pattern to remove
205	        let link_target = if let Some(ref ref_table) = ref_col.references {
206	            if ref_folder_types.contains(ref_table) {
207	                format!("ddb/{ref_table}/{target_id}.md")
208	            } else {
209	                target_id.to_string()
210	            }
211	        } else {
212	            target_id.to_string()
213	        };
214	        let ref_line = format!("- {}:: [[{}]]", col_name, link_target);
215	
216	        // Remove matching line from reference section
217	        let old_section = parsed.reference_section.clone();
218	        let new_lines: Vec<&str> = old_section
219	            .lines()
220	            .filter(|line| line.trim() != ref_line.trim())
221	            .collect();
222	        let new_section = if new_lines.is_empty() {
223	            String::new()
224	        } else {
225	            format!("{}\n", new_lines.join("\n"))
226	        };
227	
228	        // Skip commit if nothing changed
229	        if new_section == old_section {
230	            return Ok(SqlResult::Affected(0));
231	        }
232	        parsed.reference_section = new_section;
233	
234	        // Serialize
235	        let new_content = parser::serialize(&parsed);
236	
237	        // Re-index
238	        let re_parsed = parser::parse(&new_content, &path)?;
239	        self.index.index_doogat(&re_parsed)?;
240	        self.index
241	            .materialize_single(&schema, parent_id, &re_parsed)?;
242	
243	        if let Some(ref mut buf) = self.txn {
244	            buf.writes.push(PendingWrite {
245	                path,
246	                content: new_content,
247	            });
248	        } else {
249	            self.repo.commit_file(
250	                &path,
251	                &new_content,
252	                &format!("remove {col_name} ref {target_id} from {type_name} {parent_id}"),
253	            )?;
254	        }
255	
256	        Ok(SqlResult::Affected(1))
257	    }
258	}
